def e(x): return html.escape(str(x))
def alternates():
    links=[('ja','../'),('en','../en/'),('zh-Hans','../zh-cn/'),('ko','../ko/'),('es','../es/'),('fr','../fr/'),('de','../de/'),('pt-BR','../pt-br/'),('x-default','../en/')]
    return ''.join(f'<link rel="alternate" hreflang="{a}" href="{b}">' for a,b in links)
def page(code,t):
    feature_html=''.join(f'<article class="feature-card"><h3>{e(a)}</h3><p>{e(b)}</p><span class="tag">SSH NEXUS</span></article>' for a,b in t['features'])
    proof=''.join(f'<div class="proof-item"><b>{e(x)}</b></div>' for x in t['proof'])
    cards=''.join(f'<article class="screen-card {cls} reveal"><div class="screen-media"><a href="../assets/{img}" target="_blank" rel="noopener"><img src="../assets/{img}" loading="lazy" decoding="async" alt="{e(title)} — SSH Nexus"></a></div><div class="screen-copy"><h3>{e(title)}</h3><p>{e(desc)}</p></div></article>' for (title,desc),(img,cls) in zip(t['cards'],shots))
    faq=''.join(f'<details><summary>{e(q)}</summary><p>{e(a)}</p></details>' for q,a in t['faq'])
    options=''.join(f'<option value="../{("" if k=="ja" else k+"/")}" {"selected" if k==code else ""}>{v}</option>' for k,v in names.items())
    schema={"@context":"https://schema.org","@type":"SoftwareApplication","name":"SSH Nexus","applicationCategory":"DeveloperApplication","operatingSystem":"Windows 11","softwareVersion":"2.26.3","description":t['desc'],"image":"../assets/ssh-nexus-main.png","downloadUrl":"../../release/SSH-Nexus-Setup-2.26.3.exe","featureList":[x[0] for x in t['features']]}
    faq_schema={"@context":"https://schema.org","@type":"FAQPage","mainEntity":[{"@type":"Question","name":q,"acceptedAnswer":{"@type":"Answer","text":a}} for q,a in t['faq']]}
    return f'''<!doctype html><html lang="{t['lang']}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{e(t['title'])}</title><meta name="description" content="{e(t['desc'])}"><meta name="robots" content="index,follow,max-image-preview:large,max-snippet:-1"><meta name="theme-color" content="#09111d"><link rel="canonical" href="./">{alternates()}<meta property="og:type" content="website"><meta property="og:site_name" content="SSH Nexus"><meta property="og:locale" content="{t['locale']}"><meta property="og:title" content="{e(t['title'])}"><meta property="og:description" content="{e(t['desc'])}"><meta property="og:image" content="../assets/ssh-nexus-main.png"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="{e(t['title'])}"><meta name="twitter:description" content="{e(t['desc'])}"><meta name="twitter:image" content="../assets/ssh-nexus-main.png"><link rel="icon" href="../assets/app-icon.png"><link rel="manifest" href="../manifest.webmanifest"><link rel="preload" as="image" href="../assets/ssh-nexus-main.png" fetchpriority="high"><link rel="stylesheet" href="../styles.css"><script type="application/ld+json">{json.dumps(schema,ensure_ascii=False)}</script><script type="application/ld+json">{json.dumps(faq_schema,ensure_ascii=False)}</script></head><body class="locale-page"><div class="noise"></div><header class="site-header"><div class="wrap"><a class="brand" href="#top"><img src="../assets/app-icon.png" alt=""><span>SSH Nexus<small>Secure terminal for Windows</small></span></a><button class="mobile-toggle" aria-label="Menu">☰</button><nav class="nav">{''.join(f'<a href="#{x}">{e(y)}</a>' for x,y in zip(['features','workflow','screens','security'],t['nav']))}<select class="language-select" aria-label="{e(t['language'])}">{options}</select><a class="nav-download" href="../../release/SSH-Nexus-Setup-2.26.3.exe" download>{e(t['download'])}</a></nav></div></header><main id="top"><section class="hero"><div class="wrap hero-grid"><div class="hero-content reveal"><div class="eyebrow">{e(t['tag'])}</div><h1>{e(t['hero'])}</h1><p class="hero-copy">{e(t['lead'])}</p><div class="actions"><a class="button primary" href="../../release/SSH-Nexus-Setup-2.26.3.exe" download>{e(t['download'])} ↓</a><a class="button secondary" href="#features">{e(t['nav'][0])}</a></div><div class="meta"><span><i></i>{e(t['meta'])}</span></div></div><figure class="app-shot real-shot reveal"><a href="../assets/ssh-nexus-main.png" target="_blank" rel="noopener"><img src="../assets/ssh-nexus-main.png" fetchpriority="high" decoding="async" alt="SSH Nexus multi-session terminal" width="1917" height="1020"></a></figure></div></section><div class="proof"><div class="wrap proof-grid">{proof}</div></div><section id="features"><div class="wrap"><div class="section-head reveal"><div><div class="kicker">Built for daily work</div><h2>{e(t['features_title'])}</h2></div><p>{e(t['features_intro'])}</p></div><div class="feature-grid reveal">{feature_html}</div></div></section><section class="workflow" id="workflow"><div class="wrap showcase"><div class="feature-copy reveal"><div class="kicker">Window-like snapping</div><h2>{e(t['workflow_title'])}</h2><p>{e(t['workflow'])}</p></div><figure class="snap-demo actual reveal"><a href="../assets/tab-snap.png" target="_blank" rel="noopener"><img src="../assets/tab-snap.png" loading="lazy" decoding="async" alt="SSH Nexus tab snapping"></a></figure></div></section><section class="screens" id="screens"><div class="wrap"><div class="section-head reveal"><div><div class="kicker">Actual interface</div><h2>{e(t['screens_title'])}</h2></div><p>{e(t['screens_intro'])}</p></div><div class="screen-grid">{cards}</div></div></section><section class="security" id="security"><div class="wrap security-grid"><div class="security-diagram reveal">{''.join(f'<div class="security-row"><div class="security-num">0{i}</div><div><b>{e(x)}</b></div></div>' for i,x in enumerate(t['bullets'],1))}</div><div class="security-copy reveal"><div class="kicker">Security by default</div><h2>{e(t['security_title'])}</h2><p>{e(t['security'])}</p></div></div></section><section class="faq"><div class="wrap faq-grid"><h2>{e(t['faq_title'])}</h2><div class="faq-list">{faq}</div></div></section><section class="cta"><div class="wrap"><div class="cta-box reveal"><div><h2>{e(t['cta'])}</h2><p>{e(t['cta_sub'])}</p></div><a class="button primary" href="../../release/SSH-Nexus-Setup-2.26.3.exe" download>{e(t['download'])} ↓</a></div></div></section></main><footer><div class="wrap footer-row"><div class="footer-brand"><img src="../assets/app-icon.png" alt="">SSH Nexus © 2026</div><span>Version 2.26.3</span></div></footer><script>const n=document.querySelector('.nav');document.querySelector('.mobile-toggle').onclick=()=>n.classList.toggle('open');document.querySelector('.language-select').onchange=e=>location.href=e.target.value;const o=new IntersectionObserver(es=>es.forEach(e=>{{if(e.isIntersecting){{e.target.classList.add('visible');o.unobserve(e.target)}}}}),{{threshold:.1}});document.querySelectorAll('.reveal').forEach(e=>o.observe(e));</script></body></html>'''

for code,t in locales.items():
    out=ROOT/code/'index.html';out.parent.mkdir(parents=True,exist_ok=True);out.write_text(page(code,t).replace('2.26.3',VERSION),encoding='utf-8')
    print(out.relative_to(ROOT))
